using System;using System.IO;using System.Data;using System.Data.SqlClient;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;using MuEditorPhoenix;
class RewardDbTestRunner {
 static void Check(bool value,string label){if(!value)throw new Exception(label);}
 static void Reject(Action action,string label){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,label);}
 static int Main(string[] args){Guard.LocalData=Path.Combine(Path.GetTempPath(),"PhoenixRewardDb-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Guard.LocalData);string host=args.Length>0?args[0]:"localhost";string report=args.Length>1?args[1]:"database-tests.json";string name="MuEditorPhoenixTest_"+Guid.NewGuid().ToString("N");var cs=new SqlConnectionStringBuilder{DataSource=host,InitialCatalog="master",IntegratedSecurity=true,Encrypt=true,TrustServerCertificate=true,ConnectTimeout=5};bool created=false;
  try{using(var c=new SqlConnection(cs.ConnectionString)){c.Open();using(var cmd=new SqlCommand("CREATE DATABASE ["+name+"]",c)){cmd.ExecuteNonQuery();created=true;}}
   cs.InitialCatalog=name;var db=new Database{ConnectionString=cs.ConnectionString};
   db.Query(@"CREATE TABLE dbo.MEMB_INFO(memb___id varchar(10) PRIMARY KEY,mail_addr varchar(50),bloc_code char(1),AccountLevel int,AccountExpireDate smalldatetime);
CREATE TABLE dbo.MEMB_STAT(memb___id varchar(10) PRIMARY KEY,ConnectStat tinyint);
CREATE TABLE dbo.CashShopData(AccountID varchar(10) PRIMARY KEY,WCoinC int,WCoinP int,GoblinPoint int);
CREATE TABLE dbo.Character(AccountID varchar(10),Name varchar(10) PRIMARY KEY,cLevel int,Strength int,Dexterity int,Vitality int,Energy int,Leadership int,LevelUpPoint int,Money int,ResetCount int,MasterResetCount int,CtlCode tinyint,Inventory varbinary(5975));
INSERT dbo.MEMB_INFO VALUES('testuser','before@example.invalid','0',0,'20260101');INSERT dbo.MEMB_STAT VALUES('testuser',0);INSERT dbo.CashShopData VALUES('testuser',10,20,30);
INSERT dbo.Character VALUES('testuser','TestChar',200,100,200,300,400,0,10,1000,1,0,0,@inventory);",new SqlParameter("@inventory",SqlDbType.VarBinary,5975){Value=Enumerable.Repeat((byte)255,5975).ToArray()});
   db.Query(@"CREATE TABLE dbo.warehouse(AccountID varchar(10) PRIMARY KEY,Items varbinary(6000),Money int);
CREATE TABLE dbo.ExtWarehouse(AccountID varchar(10),Number int,Items varbinary(6000),Money int,PRIMARY KEY(AccountID,Number));
CREATE TABLE dbo.MasterSkillTree(Name varchar(50) PRIMARY KEY,MasterLevel int,MasterPoint int);
INSERT dbo.warehouse VALUES('testuser',@items,100);
INSERT dbo.ExtWarehouse VALUES('testuser',1,@items,200);
INSERT dbo.MasterSkillTree VALUES('TestChar',20,10);",new SqlParameter("@items",SqlDbType.VarBinary,6000){Value=Enumerable.Repeat((byte)255,6000).ToArray()});
db.Query("ALTER TABLE dbo.Character ADD Class tinyint NOT NULL DEFAULT 0");
db.Probe();Check(db.Search("test").Rows.Count==1,"search");Check(db.Search("' OR 1=1--").Rows.Count==0,"parameterized search");
   var a=db.LoadAccount("testuser");a.Rows[0]["AccountLevel"]=1;a.Rows[0]["AccountExpireDate"]=DateTime.Today.AddDays(30);a.Rows[0]["mail_addr"]="after@example.invalid";a.Rows[0]["WCoinC"]=50;db.SaveAccount(a);Check(Convert.ToInt32(db.OriginalAccount.Rows[0]["WCoinC"])==50,"account/coins transaction");
   var ch=db.LoadCharacter("TestChar");ch.Rows[0]["Strength"]=1234;byte[] item=Enumerable.Range(0,25).Select(n=>(byte)n).ToArray();db.Inventory.Set(12,item);db.SaveCharacter(ch);Check(Convert.ToInt32(db.OriginalCharacter.Rows[0]["Strength"])==1234&&db.Inventory.Slot(12).SequenceEqual(item),"character/blob transaction");
   db.Query("UPDATE dbo.MEMB_STAT SET ConnectStat=1 WHERE memb___id='testuser'");a=db.LoadAccount("testuser");a.Rows[0]["WCoinC"]=999;Reject(()=>db.SaveAccount(a),"online account must reject");Check(Convert.ToInt32(db.Query("SELECT WCoinC FROM dbo.CashShopData").Rows[0][0])==50,"online rejection unchanged");
   db.Query("UPDATE dbo.MEMB_STAT SET ConnectStat=0 WHERE memb___id='testuser'");a=db.LoadAccount("testuser");a.Rows[0]["mail_addr"]="attempt@example.invalid";db.Query("UPDATE dbo.MEMB_INFO SET mail_addr='concurrent@example.invalid'");Reject(()=>db.SaveAccount(a),"concurrent account update must reject");
   ch=db.LoadCharacter("TestChar");ch.Rows[0]["Strength"]=333;db.Query("UPDATE dbo.Character SET Money=2222");Reject(()=>db.SaveCharacter(ch),"concurrent character update must reject");Check(Convert.ToInt32(db.Query("SELECT Strength FROM dbo.Character").Rows[0][0])==1234,"rejection rolls back");
   a=db.LoadAccount("testuser");a.Rows[0]["AccountLevel"]=5;Reject(()=>db.SaveAccount(a),"invalid VIP level");

   Check(db.WarehousePages().Rows.Count==2,"warehouse pages");
   var detailed=db.LoadDetailedCharacter("TestChar");Check(db.MasterDraft!=null,"master data");db.MasterDraft.Rows[0]["MasterPoint"]=25;
   db.LoadWarehouse(-1);byte[] transferred=db.Inventory.Slot(12);db.Warehouse.Set(0,transferred);db.Inventory.Set(12,Enumerable.Repeat((byte)255,25).ToArray());db.CrossStorageDirty=true;
   Reject(()=>db.SaveCharacter(detailed),"split transfer save rejected");db.SaveWorkspace(detailed,300);
   Check(db.Inventory.Empty(12)&&db.Warehouse.Get(0).SequenceEqual(transferred),"atomic transfer");
   Check(Convert.ToInt32(db.MasterDraft.Rows[0]["MasterPoint"])==25,"master atomic update");
   detailed=db.LoadDetailedCharacter("TestChar");detailed.Rows[0]["Strength"]=4321;db.MasterDraft.Rows[0]["MasterPoint"]=99;
   db.Query("UPDATE dbo.warehouse SET Money=777 WHERE AccountID='testuser'");
   Reject(()=>db.SaveWorkspace(detailed,400),"concurrent warehouse rejects whole transaction");
   Check(Convert.ToInt32(db.Query("SELECT Strength FROM dbo.Character").Rows[0][0])==1234,"character rollback with warehouse conflict");
   Check(Convert.ToInt32(db.Query("SELECT MasterPoint FROM dbo.MasterSkillTree").Rows[0][0])==25,"master rollback with warehouse conflict");
   db.LoadWarehouse(1);db.Warehouse.Set(0,transferred);db.SaveWarehouse(500);Check(db.Warehouse.Get(0).SequenceEqual(transferred),"extended warehouse save");
   db.Query("UPDATE dbo.MEMB_STAT SET ConnectStat=1 WHERE memb___id='testuser'");Reject(()=>db.SaveWarehouse(600),"online warehouse blocked");db.Query("UPDATE dbo.MEMB_STAT SET ConnectStat=0 WHERE memb___id='testuser'");
   int count=db.BrowseCharacters("").Rows.Count;db.Query("INSERT dbo.Character(AccountID,Name,cLevel,Strength,Dexterity,Vitality,Energy,Leadership,LevelUpPoint,Money,ResetCount,MasterResetCount,CtlCode,Inventory) SELECT AccountID,'NewChar',cLevel,Strength,Dexterity,Vitality,Energy,Leadership,LevelUpPoint,Money,ResetCount,MasterResetCount,CtlCode,Inventory FROM dbo.Character WHERE Name='TestChar'");Check(db.BrowseCharacters("").Rows.Count==count+1,"new character appears on refresh query");


   db.Query("CREATE TABLE dbo.GameServerInfo(ItemCount int NOT NULL);INSERT dbo.GameServerInfo VALUES(5000)");
   db.Query(@"CREATE PROCEDURE dbo.WZ_GetItemSerial AS BEGIN SET NOCOUNT ON; DECLARE @serial int;BEGIN TRANSACTION;UPDATE dbo.GameServerInfo SET @serial=ItemCount=ItemCount+1;IF @@ERROR<>0 BEGIN ROLLBACK TRANSACTION;SELECT -1;END ELSE BEGIN COMMIT TRANSACTION;SELECT @serial;END END");
   db.Query("UPDATE dbo.Character SET Inventory=@inv WHERE Name='TestChar';UPDATE dbo.warehouse SET Items=@ware;UPDATE dbo.ExtWarehouse SET Items=@ware;",new SqlParameter("@inv",SqlDbType.VarBinary,5975){Value=Enumerable.Repeat((byte)255,5975).ToArray()},new SqlParameter("@ware",SqlDbType.VarBinary,6000){Value=Enumerable.Repeat((byte)255,6000).ToArray()});
   string xml=Path.Combine(Guard.LocalData,"Item.xml");File.WriteAllText(xml,"<ItemList><Section Index='0'><Item Index='1' Name='Synthetic Reward' Width='2' Height='2'/></Section><Section Index='20'><Item Index='248' Name='Synthetic Modern Reward' Width='1' Height='1'/></Section></ItemList>");var catalog=new Catalog();catalog.Load(xml);
   detailed=db.LoadDetailedCharacter("TestChar");db.LoadWarehouse(-1);var draft=new ItemBuffer(db.Inventory.Data);var spec=new RewardSpec{ItemId=1,Level=15,Durability=60,Additional=28,Excellent=63,Skill=true,Luck=true,Copies=2};var awardSlots=draft.AddRewards(spec,catalog,12,76);Check(Convert.ToInt32(db.Query("SELECT ItemCount FROM dbo.GameServerInfo").Rows[0][0])==5000,"draft consumes no serial");
   db.Inventory.Data=(byte[])draft.Data.Clone();db.InventoryNewItems=draft.NewItems.ToDictionary(p=>p.Key,p=>p.Value);db.SaveCharacter(detailed);Check(db.LastCreatedItems.Count==2&&db.LastCreatedItems.Select(x=>x.Serial).Distinct().Count()==2,"unique inventory award serials");foreach(int slot in awardSlots){byte[] value=db.Inventory.Slot(slot);Check(ItemCodec25.Id(value)==1&&ItemCodec25.Serial(value)>5000&&4*((value[1]&3)+((value[7]&64)>>4))==28,"inventory award roundtrip");}
   Check(Convert.ToInt32(db.Query("SELECT ItemCount FROM dbo.GameServerInfo").Rows[0][0])==5002,"server counter advances exactly");
   var modernSpec=new RewardSpec{ItemId=10488,Durability=1,Additional=28};db.LoadWarehouse(-1);int modernSlot=db.Warehouse.AddRewards(modernSpec,catalog,0,120)[0];db.SaveWarehouse(300);Check(db.Warehouse.Id(modernSlot)==10488&&ItemCodec25.Serial(db.Warehouse.Get(modernSlot))==5003,"modern category warehouse award");
   detailed=db.LoadDetailedCharacter("TestChar");draft=new ItemBuffer(db.Inventory.Data);spec.Copies=1;int moved=draft.AddRewards(spec,catalog,12,76)[0];ItemBuffer.Move(draft,moved,db.Warehouse,10,catalog,0,120);db.CrossStorageDirty=true;db.Inventory.Data=(byte[])draft.Data.Clone();db.InventoryNewItems=draft.NewItems.ToDictionary(p=>p.Key,p=>p.Value);db.SaveWorkspace(detailed,300);Check(db.LastCreatedItems.Count==1&&db.Warehouse.NewItems.Count==0&&ItemCodec25.Serial(db.Warehouse.Get(10))==5004,"moved draft materializes in final destination only");
   int failedSlot=db.Warehouse.AddRewards(modernSpec,catalog,0,120)[0];int beforeSerial=Convert.ToInt32(db.Query("SELECT ItemCount FROM dbo.GameServerInfo").Rows[0][0]);byte[] beforeWarehouse=(byte[])db.Query("SELECT Items FROM dbo.warehouse WHERE AccountID='testuser'").Rows[0][0];
   db.Query("CREATE TRIGGER dbo.FailSyntheticAward ON dbo.warehouse AFTER UPDATE AS BEGIN THROW 50001,'Synthetic late failure',1;END");Reject(()=>db.SaveWarehouse(400),"late failure rejects award");Check(Convert.ToInt32(db.Query("SELECT ItemCount FROM dbo.GameServerInfo").Rows[0][0])==beforeSerial,"late failure rolls back native serial counter");Check(((byte[])db.Query("SELECT Items FROM dbo.warehouse WHERE AccountID='testuser'").Rows[0][0]).SequenceEqual(beforeWarehouse),"late failure rolls back items");Check(db.Warehouse.NewItems.ContainsKey(failedSlot)&&ItemCodec25.Serial(db.Warehouse.Get(failedSlot))==0,"failed award remains retryable draft");db.Query("DROP TRIGGER dbo.FailSyntheticAward");db.SaveWarehouse(400);Check(db.LastCreatedItems.Single().Serial==beforeSerial+1,"retry commits once without duplicate serial");
   int offlineSlot=db.Warehouse.AddRewards(modernSpec,catalog,0,120)[0];beforeSerial=Convert.ToInt32(db.Query("SELECT ItemCount FROM dbo.GameServerInfo").Rows[0][0]);db.Query("UPDATE dbo.MEMB_STAT SET ConnectStat=1 WHERE memb___id='testuser'");Reject(()=>db.SaveWarehouse(400),"online account rejects reward");Check(Convert.ToInt32(db.Query("SELECT ItemCount FROM dbo.GameServerInfo").Rows[0][0])==beforeSerial,"online block consumes no serial");db.Query("UPDATE dbo.MEMB_STAT SET ConnectStat=0 WHERE memb___id='testuser'");db.Warehouse.CancelNew(offlineSlot);
   db.Query("INSERT dbo.MEMB_INFO VALUES('otheruser','other@example.invalid','0',0,'20260101');INSERT dbo.MEMB_STAT VALUES('otheruser',0);INSERT dbo.warehouse VALUES('otheruser',@items,0);",new SqlParameter("@items",SqlDbType.VarBinary,6000){Value=Enumerable.Repeat((byte)255,6000).ToArray()});
   var left=new Database{ConnectionString=cs.ConnectionString};var right=new Database{ConnectionString=cs.ConnectionString};left.LoadAccount("testuser");right.LoadAccount("otheruser");left.LoadWarehouse(-1);right.LoadWarehouse(-1);left.Warehouse.AddRewards(modernSpec,catalog,0,120);right.Warehouse.AddRewards(modernSpec,catalog,0,120);var taskA=System.Threading.Tasks.Task.Run(()=>left.SaveWarehouse(0));var taskB=System.Threading.Tasks.Task.Run(()=>right.SaveWarehouse(0));System.Threading.Tasks.Task.WaitAll(taskA,taskB);Check(left.LastCreatedItems.Single().Serial!=right.LastCreatedItems.Single().Serial,"parallel awards receive distinct native serials");
   File.WriteAllText(report,new JavaScriptSerializer().Serialize(new{status="PASS",isolatedDatabase=true,productionWrites=false,tests=new[]{"schema probe","parameterized search","VIP/account/coins transaction","character/inventory transaction","online account blocked","optimistic conflict blocked","invalid VIP blocked","encrypted local backup","base and extended warehouse","atomic cross-storage transfer","Master data save","warehouse conflict rolls back character and Master","split transfer blocked","new character refresh","reward inventory and warehouse","additional +28 stored correctly","5-bit modern item ID","native serial counter","deferred serial allocation","new draft transfer","late failure rolls back items and serial","retry does not duplicate","online award blocked","concurrent awards unique"}}));Console.WriteLine("PASS: isolated database integration tests");return 0;
  }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{if(created){cs.InitialCatalog="master";SqlConnection.ClearAllPools();using(var c=new SqlConnection(cs.ConnectionString)){c.Open();using(var cmd=new SqlCommand("ALTER DATABASE ["+name+"] SET SINGLE_USER WITH ROLLBACK IMMEDIATE; DROP DATABASE ["+name+"]",c)){cmd.ExecuteNonQuery();}}}}
 }
}
